pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 q) public {
        // Universal rule: any interface the contract claims to support implies
        // it also supports the ERC-165 interface id 0x01ffc9a7 (via super).
        bool claimsQ = c.supportsInterface(q);
        bool claims165 = c.supportsInterface(bytes4(0x01ffc9a7));
        assertTrue(!claimsQ || claims165, "supporting any interface implies supporting ERC-165");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        // Rule (ERC-165 conformance of C's resolved diamond): C supports exactly
        // {IAccessControl, IERC165}. For any admissible bytes4 input q,
        //   c.supportsInterface(q) == (q == type(IAccessControl).interfaceId || q == type(IERC165).interfaceId)
        // The reference satisfies this for every q; the mutant, having dropped
        // `|| super.supportsInterface(interfaceId)`, returns false for
        // q == type(IERC165).interfaceId (0x01ffc9a7), violating the equality.
        bool expected = (interfaceId == type(IAccessControl).interfaceId) ||
                        (interfaceId == type(IERC165).interfaceId);
        assertTrue(c.supportsInterface(interfaceId) == expected);
    }
}

