pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 interfaceId) public {
        // Rule: whenever c declares support for ANY interface id (here the fuzzed one,
        // which the fuzzer may set to the IAccessControl id), c must also declare
        // support for the ERC-165 interface id itself (served in the reference by
        // the `|| super.supportsInterface(interfaceId)` disjunct).
        bool claimsSupport = c.supportsInterface(interfaceId);
        bool supportsERC165 = c.supportsInterface(type(IERC165).interfaceId);

        assertTrue(!claimsSupport || supportsERC165);
    }
}

