// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // The timelock contract itself holds TIMELOCK_ADMIN_ROLE, the admin of PROPOSER_ROLE.
        vm.prank(address(c));
        c.grantRole(c.PROPOSER_ROLE(), actor);

        // General rule: a granted role is reported as held by hasRole for any account.
        assertTrue(c.hasRole(c.PROPOSER_ROLE(), actor));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role) public {
        // Rule: getRoleAdmin(r) == r holds only for TIMELOCK_ADMIN_ROLE.
        // Reference stores TIMELOCK_ADMIN_ROLE as admin of the three configured roles
        // and bytes32(0) for all others, so self-administration happens solely for
        // TIMELOCK_ADMIN_ROLE. The mutant returns the queried role itself, so any
        // role != TIMELOCK_ADMIN_ROLE yields a self-administered result.
        bytes32 admin = c.getRoleAdmin(role);
        assertTrue(admin != role || role == c.TIMELOCK_ADMIN_ROLE());
    }
}
